package com.careerpilot.service;
import org.springframework.beans.factory.annotation.Value; import org.springframework.http.*; import org.springframework.stereotype.Service; import org.springframework.web.client.RestClient; import java.util.*;
@Service public class OpenAiService {
 @Value("${app.openai.api-key:}") private String apiKey; @Value("${app.openai.model:gpt-4o-mini}") private String model;
 public String generate(String task,String input){ if(apiKey==null||apiKey.isBlank()) return "OpenAI is not configured. Add OPENAI_API_KEY to your environment and restart the backend.\n\nRequested task: "+task; Map<String,Object> payload=Map.of("model",model,"messages",List.of(Map.of("role","system","content","You are CareerPilot, a practical career coach. Be specific, structured, honest, and concise. Do not invent facts about the candidate."),Map.of("role","user","content",task+"\n\nCandidate information:\n"+input)),"temperature",0.4); Map<?,?> response=RestClient.create("https://api.openai.com").post().uri("/v1/chat/completions").header("Authorization","Bearer "+apiKey).contentType(MediaType.APPLICATION_JSON).body(payload).retrieve().body(Map.class); try { List<?> choices=(List<?>)response.get("choices"); Map<?,?> choice=(Map<?,?>)choices.get(0); Map<?,?> message=(Map<?,?>)choice.get("message"); return String.valueOf(message.get("content")); } catch(Exception e){throw new RuntimeException("Could not read the AI response.");} }
}
